/bin/zsh -c "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { Either, Schema } from 'effect';
import { importManifest, manifestSchema } from './dist/index.js';
const parcel = { reference: ' p1 ', grams: 300, service: 'standard' };
const valid = { partner: ' shop ', parcels: [parcel] };
const invalid = [undefined, null, false, 1, 'x', [], {}, {parcels: [parcel]}, {...valid, partner: 5}, {...valid, partner: ' '}, {...valid, parcels: []}, {...valid, parcels: {}}, {...valid, parcels: [null]}, {...valid, parcels: [parcel, {...parcel, reference: 'p1'}]}];
for (const key of ['reference', 'grams', 'service']) {
  const missing = {...parcel}; delete missing[key];
  invalid.push({...valid, parcels: [missing]});
}
for (const grams of [undefined, null, '300', NaN, Infinity, -Infinity, 0, -1, 1.5]) invalid.push({...valid, parcels: [{...parcel, grams}]});
for (const reference of [null, 1, '', '  ']) invalid.push({...valid, parcels: [{...parcel, reference}]});
for (const service of [null, 1, '', 'priority', ' standard ']) invalid.push({...valid, parcels: [{...parcel, service}]});
for (const input of invalid) {
  assert.deepEqual(importManifest(input), {ok: false, reason: 'invalid-manifest'});
  assert.equal(Either.isLeft(Schema.decodeUnknownEither(manifestSchema)(input)), true);
}
const input = {...valid, extra: {}, parcels: [{...parcel, extra: {}}, {reference: ' p2 ', grams: 1, service: 'express'}]};
const before = structuredClone(input);
const expected = {partner: 'shop', parcels: [{reference: 'p1', grams: 300, service: 'standard'}, {reference: 'p2', grams: 1, service: 'express'}]};
const result = importManifest(input);
assert.deepEqual(result, {ok: true, manifest: expected});
assert.deepEqual(Schema.decodeUnknownSync(manifestSchema)(input), expected);
assert.deepEqual(input, before);
assert.notEqual(result.manifest, input);
assert.notEqual(result.manifest.parcels, input.parcels);
assert.notEqual(result.manifest.parcels[0], input.parcels[0]);
input.parcels[0].grams = 999;
assert.deepEqual(result.manifest, expected);
console.log('Schema/importer validation, normalization, stripping, order, and isolation checks passed.');
JS"

changes.before:
import { Schema } from "effect";
import type { PartnerManifest } from "./types.js";
export const manifestSchema: Schema.Schema<PartnerManifest, unknown> = Schema.Unknown as Schema.Schema<PartnerManifest, unknown>;

changes.after:
import { Schema } from "effect";
const nonBlankString = Schema.Trim.pipe(Schema.nonEmptyString());

const parcelSchema = Schema.Struct({
  reference: nonBlankString,
  grams: Schema.Number.pipe(Schema.finite(), Schema.int(), Schema.positive()),
  service: Schema.Literal("standard", "express"),
});

export const manifestSchema = Schema.Struct({
  partner: nonBlankString,
  parcels: Schema.Array(parcelSchema).pipe(Schema.minItems(1)),
}).pipe(
  Schema.filter(({ parcels }) =>
    new Set(parcels.map(({ reference }) => reference)).size === parcels.length
  ),
);
